const readyRows = $input.all().map((item) => item.json);

// 2026-05-18: deduplicate by revenue_event_key BEFORE upsert.
// The source view profit_revenue_events_ready_for_recognition can emit
// multiple rows per revenue_event_key when a revenue event has both a
// manual_recognition_approved override AND an auto trigger (e.g. tax_filed).
// Sending both rows to Supabase causes "ON CONFLICT DO UPDATE command
// cannot affect row a second time" — Postgres rejects multiple updates to
// the same target row in one statement.
//
// Resolution policy: operator intent wins. Prefer manual_recognition_approved
// over any auto trigger. If multiple manuals, use the latest by
// recognition_date_to_apply. If no manual, pick the first auto trigger.
const PRIORITY = { manual_recognition_approved: 0 };
function priority(row) {
  return PRIORITY[row.trigger_type] ?? 1;
}
function isLater(a, b) {
  return String(a.recognition_date_to_apply ?? '') > String(b.recognition_date_to_apply ?? '');
}
const byKey = new Map();
let duplicatesDropped = 0;
const duplicateLog = [];
for (const row of readyRows) {
  const key = row.revenue_event_key;
  if (!byKey.has(key)) {
    byKey.set(key, row);
    continue;
  }
  const existing = byKey.get(key);
  const incomingPri = priority(row);
  const existingPri = priority(existing);
  duplicatesDropped += 1;
  let winner = existing;
  if (incomingPri < existingPri) {
    winner = row;
  } else if (incomingPri === existingPri && isLater(row, existing)) {
    winner = row;
  }
  byKey.set(key, winner);
  duplicateLog.push({
    revenue_event_key: key,
    kept: winner.trigger_type + ':' + winner.recognition_trigger_key,
    dropped: (winner === existing ? row : existing).trigger_type + ':' + (winner === existing ? row : existing).recognition_trigger_key,
  });
}
const dedupedRows = Array.from(byKey.values());

const rows = dedupedRows.map((row) => ({
  revenue_event_key: row.revenue_event_key,
  anchor_line_item_id: row.anchor_line_item_id ?? null,
  anchor_invoice_id: row.anchor_invoice_id,
  anchor_relationship_id: row.anchor_relationship_id ?? null,
  macro_service_type: row.macro_service_type,
  source_amount: Number(row.source_amount ?? 0),
  recognized_amount: Number(row.recognized_amount_to_apply ?? 0),
  recognition_status: row.next_recognition_status ?? 'recognized_by_completion_trigger',
  recognition_rule: row.recognition_rule,
  candidate_period_month: row.candidate_period_month ?? null,
  recognition_date: row.recognition_date_to_apply,
  recognition_period_month: row.recognition_period_month_to_apply,
  trigger_source: row.source_system,
  trigger_reference: row.trigger_reference_to_apply,
  notes: `Recognized by ${row.trigger_type} trigger ${row.recognition_trigger_key}.`,
  loaded_at: new Date().toISOString(),
}));

const recognizedAmount = rows.reduce((sum, row) => sum + Number(row.recognized_amount ?? 0), 0);
const byMacro = rows.reduce((acc, row) => {
  acc[row.macro_service_type] = (acc[row.macro_service_type] ?? 0) + 1;
  return acc;
}, {});

return [
  {
    json: {
      rows,
      summary: {
        readyRevenueEventCount: rows.length,
        duplicatesDropped,
        duplicateLog,
        recognizedAmount: Math.round(recognizedAmount * 100) / 100,
        byMacro,
      },
    },
  },
];

const rows = $input.all().map((item) => item.json);
const recognizedAmount = rows.reduce((sum, row) => sum + Number(row.recognized_amount ?? 0), 0);
const byMacro = rows.reduce((acc, row) => {
  acc[row.macro_service_type] = (acc[row.macro_service_type] ?? 0) + 1;
  return acc;
}, {});

return [
  {
    json: {
      status: 'ok',
      appliedRevenueEventCount: rows.length,
      recognizedAmount: Math.round(recognizedAmount * 100) / 100,
      byMacro,
      sample: rows.slice(0, 10),
    },
  },
];
